(7740314, 1276609, 30861, '<td valign="top">Well, those butt-ugly wheels drag down the "perfection" quotient of the vehicle, but it''s still pretty luscious :-)</td>', 'Well, those butt-ugly wheels drag down the "perfection" quotient of the vehicle, but it''s still pretty luscious :-)', '2023-03-17 02:27:22.000000', NULL, 1),
(7740633, 1276705, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2023-03-22 13:34:23.000000', NULL, 1),
